1	export interface Item {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	}
7	
8	export interface QuoteStep {
9	  op: "quote";
10	  items: Item[];
11	}
12	
13	export interface Damage {
14	  itemType: string;
15	  amount: number;
16	}
17	
18	export interface ClaimStep {
19	  op: "claim";
20	  policy: number;
21	  incident: { cause: string; damages: Damage[] };
22	}
23	
24	export type Step = QuoteStep | ClaimStep;
25	
26	export interface Scenario {
27	  customer: { yearsWithMHPCO: number };
28	  steps: Step[];
29	}
30	
31	export interface QuoteResult {
32	  premium: number;
33	}
34	
35	export interface ClaimResult {
36	  payout: number;
37	  remainingCap: number;
38	}
39	
40	export interface ScenarioResults {
41	  results: (QuoteResult | ClaimResult)[];
42	}
43	
44	const PROCESSING_FEE = 5;
45	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
46	
47	const BASE_PREMIUMS: Record<string, number> = {
48	  sword: 100,
49	  amulet: 60,
50	  staff: 80,
51	  potion: 40,
52	  rune: 25,
53	};
54	
55	const sumBasePremiums = (items: Item[]): number =>
56	  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
57	
58	const quotePremium = (items: Item[]): number => {
59	  const basePremium = sumBasePremiums(items);
60	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
61	  return Math.ceil(basePremium + firstInsuranceSurcharge + PROCESSING_FEE);
62	};
63	
64	export const runScenario = (scenario: Scenario): ScenarioResults => ({
65	  results: scenario.steps.map((step) => ({
66	    premium: quotePremium((step as QuoteStep).items),
67	  })),
68	});
