// Premiums are rounded up, in the MHPCO's favour; only the final premium is
// rounded, intermediate amounts stay fractional.
const roundInMHPCOsFavour = Math.ceil;

const quotePremium = (items: Item[]): number => {
  const basePremium = sumBasePremiums(items);
  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
  return roundInMHPCOsFavour(
    basePremium + firstInsuranceSurcharge + PROCESSING_FEE,
  );
};
